def total = ctx.rigsignal?.cpu?.total_utilisation_pct;
if (total != null && (total < 0 || total > 100)) {
  throw new Exception('rigsignal.cpu.total_utilisation_pct must be 0-100, got: ' + total);
}
def game = ctx.rigsignal?.cpu?.game_utilisation_pct;
if (game != null && (game < 0 || game > 100)) {
  throw new Exception('rigsignal.cpu.game_utilisation_pct must be 0-100, got: ' + game);
}
